import React, { useState, forwardRef, ElementRef } from 'react';
import { StyledGroup, StyledItem, Label } from './SegmentedControl.styles';
import { SegmentedControlTypes } from './SegmentedControl.types';

const SegmentedControl = forwardRef<ElementRef<typeof StyledGroup>, SegmentedControlTypes>(
  ({ onValueChange, defaultValue, options, ...props }, fowardedRef): JSX.Element => {
    const [stateValue, setStateValue] = useState(defaultValue ?? options[0].value);

    if (options.length < 2 || options.length > 3) {
      // eslint-disable-next-line no-console
      console.warn('Options length must be equal to 2 or 3.');
      return <></>;
    }

    return (
      <StyledGroup
        onValueChange={(itemValue) => {
          if (itemValue) {
            // eslint-disable-next-line no-unused-expressions
            !!onValueChange && onValueChange(itemValue);
            setStateValue(itemValue);
          }
        }}
        ref={fowardedRef}
        value={stateValue}
        {...props}
        type="single"
        orientation="horizontal"
      >
        {options.map((item) => (
          <StyledItem key={item.value} value={item.value}>
            <Label>{item.label}</Label>
          </StyledItem>
        ))}
      </StyledGroup>
    );
  }
);

export default SegmentedControl;
